-- Behavioural regression suite for lead source and the public web form
-- (migration 249).
--
-- contacts.lead_source takes only the seven sources (or NULL) and is
-- filled by automatic writers only while empty
-- (contact_set_lead_source_if_empty). The web form's settings are read
-- and written by owners/admins only, through RPCs (no client reads the
-- table, so the token never reaches anon); the token is generated by the
-- database. web_form_submit answers an unknown and a disabled token the
-- same, creates the contact (owned by the workspace owner) or, since 256,
-- leaves an existing one's name and email alone (the submitted values go
-- in the task), sets lead_source 'web_form' if empty, opens one
-- follow_up task per contact per 10 minutes, and never writes consent.
--
-- ONE statement on purpose: `supabase db query --file` sends the file
-- as a single prepared statement and rejects several. Fixtures are
-- rolled back by a sentinel exception; results survive in variables.

DO $verify$
DECLARE
  u_owner  UUID := '00000000-0000-4000-8000-000000249001';
  u_admin  UUID := '00000000-0000-4000-8000-000000249002';
  u_agent  UUID := '00000000-0000-4000-8000-000000249003';
  a_acct   UUID;
  v_tok    TEXT;
  v_tok2   TEXT;
  v_j      JSONB;
  c_new    UUID;
  c_old    UUID;
  c_out    UUID;
  v_t      TEXT;
  v_n      INT;
  v_b      BOOLEAN;
  v_ts     TIMESTAMPTZ;
  r        TEXT;
  n        INT := 0;
  failed   TEXT[] := '{}';
BEGIN
  BEGIN
  EXECUTE $fn$
    CREATE FUNCTION pg_temp.wlf_try(p_uid uuid, p_sql text)
    RETURNS text LANGUAGE plpgsql AS $body$
    DECLARE v text; st text; h text; m text;
    BEGIN
      BEGIN
        PERFORM set_config('request.jwt.claim.sub', p_uid::text, true);
        PERFORM set_config('request.jwt.claims',
          json_build_object('sub', p_uid, 'role', 'authenticated')::text, true);
        SET LOCAL ROLE authenticated;
        IF p_sql ILIKE 'select%' THEN
          EXECUTE p_sql INTO v;
        ELSE
          EXECUTE p_sql;
        END IF;
        RESET ROLE;
        PERFORM set_config('request.jwt.claim.sub', '', true);
        PERFORM set_config('request.jwt.claims', '', true);
        RETURN coalesce(nullif(v, ''), 'ok');
      EXCEPTION WHEN OTHERS THEN
        GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, h = PG_EXCEPTION_HINT,
                                m = MESSAGE_TEXT;
        RESET ROLE;
        PERFORM set_config('request.jwt.claim.sub', '', true);
        PERFORM set_config('request.jwt.claims', '', true);
        RETURN format('ERROR %s %s: %s', st, coalesce(h, ''), m);
      END;
    END $body$
  $fn$;

  EXECUTE $fn$
    CREATE FUNCTION pg_temp.wlf_raw(p_sql text)
    RETURNS text LANGUAGE plpgsql AS $body$
    DECLARE v text; st text; h text; m text;
    BEGIN
      IF p_sql ILIKE 'select%' THEN
        EXECUTE p_sql INTO v;
      ELSE
        EXECUTE p_sql;
      END IF;
      RETURN coalesce(nullif(v, ''), 'ok');
    EXCEPTION WHEN OTHERS THEN
      GET STACKED DIAGNOSTICS st = RETURNED_SQLSTATE, h = PG_EXCEPTION_HINT,
                              m = MESSAGE_TEXT;
      RETURN format('ERROR %s %s: %s', st, coalesce(h, ''), m);
    END $body$
  $fn$;

  INSERT INTO auth.users (id, email) VALUES
    (u_owner, 'wlf-owner@example.invalid'),
    (u_admin, 'wlf-admin@example.invalid'),
    (u_agent, 'wlf-agent@example.invalid')
  ON CONFLICT DO NOTHING;
  SELECT id INTO a_acct FROM accounts WHERE owner_user_id = u_owner;
  IF a_acct IS NULL THEN
    RAISE EXCEPTION 'fixture: auth.users trigger did not provision an account';
  END IF;
  UPDATE profiles SET account_id = a_acct, account_role = 'admin' WHERE user_id = u_admin;
  UPDATE profiles SET account_id = a_acct, account_role = 'agent' WHERE user_id = u_agent;

  -- ---- lead_source column --------------------------------------------
  INSERT INTO contacts (account_id, user_id, phone, name, lead_source)
    VALUES (a_acct, u_agent, '971500249010', 'Existing', 'manual') RETURNING id INTO c_old;
  r := pg_temp.wlf_raw(format(
    'UPDATE contacts SET lead_source = ''bogus'' WHERE id = %L', c_old));
  n := n + 1;
  IF r NOT LIKE 'ERROR 23514%' THEN
    failed := array_append(failed, ('an unknown lead source was stored: ' || r)::text);
  END IF;
  n := n + 1;
  IF (SELECT lead_source_detail FROM contacts WHERE id = c_old) IS DISTINCT FROM '{}'::jsonb THEN
    failed := array_append(failed, 'lead_source_detail does not default to {}'::text);
  END IF;
  r := pg_temp.wlf_try(u_agent, format(
    'UPDATE contacts SET lead_source = ''import'' WHERE id = %L', c_old));
  n := n + 1;
  IF r <> 'ok' OR (SELECT lead_source FROM contacts WHERE id = c_old) <> 'import' THEN
    failed := array_append(failed, ('the contact''s owner could not correct its source: ' || r)::text);
  END IF;
  UPDATE contacts SET lead_source = 'manual' WHERE id = c_old;

  -- ---- if-empty setter -----------------------------------------------
  INSERT INTO contacts (account_id, user_id, phone, name)
    VALUES (a_acct, u_agent, '971500249011', 'Blank') RETURNING id INTO c_out;
  v_b := contact_set_lead_source_if_empty(a_acct, c_out, 'ad', '{"source_id":"1"}');
  n := n + 1;
  IF v_b IS NOT TRUE OR (SELECT lead_source FROM contacts WHERE id = c_out) <> 'ad' THEN
    failed := array_append(failed, 'the setter did not fill an empty source'::text);
  END IF;
  v_b := contact_set_lead_source_if_empty(a_acct, c_out, 'web_form', '{}');
  n := n + 1;
  IF v_b IS NOT FALSE OR (SELECT lead_source FROM contacts WHERE id = c_out) <> 'ad'
     OR (SELECT lead_source_detail ->> 'source_id' FROM contacts WHERE id = c_out) IS DISTINCT FROM '1' THEN
    failed := array_append(failed, 'the setter overwrote a source that was set'::text);
  END IF;
  r := pg_temp.wlf_raw(format(
    'SELECT contact_set_lead_source_if_empty(%L, %L, ''web_form'', ''{}'')', gen_random_uuid(), c_old));
  n := n + 1;
  IF r <> 'false' THEN
    failed := array_append(failed, ('the setter wrote across accounts: ' || r)::text);
  END IF;

  -- ---- settings: who ---------------------------------------------------
  r := pg_temp.wlf_try(u_agent, 'SELECT web_form_get()');
  n := n + 1;
  IF r NOT LIKE 'ERROR 42501 not_admin%' THEN
    failed := array_append(failed, ('an agent read the web form: ' || r)::text);
  END IF;
  r := pg_temp.wlf_try(u_agent, 'SELECT web_form_set(true, ''{}'', false)');
  n := n + 1;
  IF r NOT LIKE 'ERROR 42501 not_admin%' THEN
    failed := array_append(failed, ('an agent changed the web form: ' || r)::text);
  END IF;
  r := pg_temp.wlf_try(u_admin, 'SELECT web_form_get()');
  n := n + 1;
  IF r LIKE 'ERROR%' OR (r::jsonb ->> 'enabled') <> 'false' OR (r::jsonb -> 'token') <> 'null'::jsonb THEN
    failed := array_append(failed, ('before the first save the form is not off and tokenless: ' || r)::text);
  END IF;
  r := pg_temp.wlf_try(u_admin, 'SELECT web_form_set(false, ARRAY[''http://example.com''], false)');
  n := n + 1;
  IF r NOT LIKE 'ERROR 22023 bad_origin%' THEN
    failed := array_append(failed, ('an http origin was accepted: ' || r)::text);
  END IF;
  r := pg_temp.wlf_try(u_admin, 'SELECT web_form_set(false, ARRAY[''https://example.com/path''], false)');
  n := n + 1;
  IF r NOT LIKE 'ERROR 22023 bad_origin%' THEN
    failed := array_append(failed, ('an origin with a path was accepted: ' || r)::text);
  END IF;
  r := pg_temp.wlf_try(u_admin, 'SELECT web_form_set(false, ARRAY[''https://www.example.com'', ''https://www.example.com''], false)');
  n := n + 1;
  IF r LIKE 'ERROR%' THEN
    failed := array_append(failed, ('an admin could not save the form: ' || r)::text);
  ELSE
    v_tok := r::jsonb ->> 'token';
    IF v_tok IS NULL OR v_tok !~ '^[0-9a-f]{64}$'
       OR (r::jsonb -> 'allowed_origins') <> '["https://www.example.com"]'::jsonb
       OR (r::jsonb ->> 'enabled') <> 'false' THEN
      failed := array_append(failed, ('the first save returned: ' || r)::text);
    END IF;
  END IF;

  -- ---- nobody but the RPCs reads the table ------------------------------
  n := n + 1;
  IF has_table_privilege('anon', 'public.web_lead_forms', 'SELECT')
     OR has_table_privilege('authenticated', 'public.web_lead_forms', 'SELECT')
     OR has_table_privilege('authenticated', 'public.web_lead_forms', 'UPDATE') THEN
    failed := array_append(failed, 'clients hold a privilege on web_lead_forms'::text);
  END IF;
  n := n + 1;
  IF has_function_privilege('authenticated', 'public.web_form_submit(text, text, text, text, text, jsonb)', 'EXECUTE')
     OR has_function_privilege('anon', 'public.web_form_submit(text, text, text, text, text, jsonb)', 'EXECUTE')
     OR has_function_privilege('anon', 'public.web_form_public_config(text)', 'EXECUTE')
     OR has_function_privilege('authenticated', 'public.web_form_public_config(text)', 'EXECUTE')
     OR has_function_privilege('authenticated', 'public.contact_set_lead_source_if_empty(uuid, uuid, text, jsonb)', 'EXECUTE')
     OR has_function_privilege('anon', 'public.web_form_get()', 'EXECUTE')
     OR has_function_privilege('anon', 'public.web_form_set(boolean, text[], boolean)', 'EXECUTE') THEN
    failed := array_append(failed, 'clients may execute a service-role web form function'::text);
  END IF;
  n := n + 1;
  IF NOT has_function_privilege('service_role', 'public.web_form_submit(text, text, text, text, text, jsonb)', 'EXECUTE')
     OR NOT has_function_privilege('service_role', 'public.web_form_public_config(text)', 'EXECUTE')
     OR NOT has_function_privilege('service_role', 'public.contact_set_lead_source_if_empty(uuid, uuid, text, jsonb)', 'EXECUTE')
     OR NOT has_function_privilege('authenticated', 'public.web_form_set(boolean, text[], boolean)', 'EXECUTE') THEN
    failed := array_append(failed, 'the route or the panel cannot execute its function'::text);
  END IF;

  -- ---- disabled = unknown -----------------------------------------------
  n := n + 1;
  IF web_form_public_config(v_tok) IS NOT NULL
     OR web_form_public_config(repeat('a', 64)) IS NOT NULL THEN
    failed := array_append(failed, 'a disabled or unknown form has a public config'::text);
  END IF;
  v_j := web_form_submit(v_tok, 'Lead', '971500249020', NULL, 'hi', '{}');
  n := n + 1;
  IF v_j ->> 'status' <> 'not_found'
     OR EXISTS (SELECT 1 FROM contacts WHERE account_id = a_acct AND phone_normalized = '971500249020') THEN
    failed := array_append(failed, ('a disabled form accepted a lead: ' || v_j::text)::text);
  END IF;
  v_j := web_form_submit(repeat('b', 64), 'Lead', '971500249020', NULL, 'hi', '{}');
  n := n + 1;
  IF v_j <> '{"status":"not_found"}'::jsonb THEN
    failed := array_append(failed, ('an unknown token answered differently: ' || v_j::text)::text);
  END IF;

  r := pg_temp.wlf_try(u_admin, 'SELECT web_form_set(true, ARRAY[''https://www.example.com''], false)');
  n := n + 1;
  IF r LIKE 'ERROR%' OR r::jsonb ->> 'token' <> v_tok THEN
    failed := array_append(failed, ('switching on changed the token or failed: ' || r)::text);
  END IF;
  n := n + 1;
  IF web_form_public_config(v_tok) IS DISTINCT FROM '{"allowed_origins":["https://www.example.com"]}'::jsonb THEN
    failed := array_append(failed, ('the public config is: ' || coalesce(web_form_public_config(v_tok)::text, 'NULL'))::text);
  END IF;

  -- ---- a new lead --------------------------------------------------------
  r := pg_temp.wlf_raw(format(
    'SELECT web_form_submit(%L, ''x'', ''+971 50'', NULL, NULL, ''{}'')', v_tok));
  n := n + 1;
  IF r NOT LIKE 'ERROR 22023 bad_phone%' THEN
    failed := array_append(failed, ('an un-normalised phone was accepted: ' || r)::text);
  END IF;
  v_j := web_form_submit(v_tok, '  Web Lead ', '971500249020', 'Lead@Example.com',
                         'Please call me', '{"page_url":"https://www.example.com/apply"}');
  c_new := (v_j ->> 'contact_id')::uuid;
  n := n + 1;
  IF v_j ->> 'status' <> 'ok' OR (v_j ->> 'contact_created') <> 'true'
     OR (v_j ->> 'task_created') <> 'true' THEN
    failed := array_append(failed, ('a first submission returned: ' || v_j::text)::text);
  END IF;
  n := n + 1;
  IF NOT EXISTS (
    SELECT 1 FROM contacts
     WHERE id = c_new AND account_id = a_acct AND user_id = u_owner
       AND name = 'Web Lead' AND email = 'lead@example.com'
       AND lead_source = 'web_form'
       AND lead_source_detail ->> 'page_url' = 'https://www.example.com/apply'
       AND lead_source_detail ->> 'form' = 'web'
       AND opted_out_at IS NULL) THEN
    failed := array_append(failed, 'the new contact is not the owner''s web_form lead'::text);
  END IF;
  SELECT count(*) INTO v_n FROM tasks
   WHERE contact_id = c_new AND kind = 'follow_up' AND source = 'automation'
     AND assigned_to IS NULL AND status = 'open' AND note = 'Please call me'
     AND title = 'New web lead';
  n := n + 1;
  IF v_n <> 1 THEN
    failed := array_append(failed, ('the new lead has ' || v_n || ' follow-up tasks')::text);
  END IF;

  -- The same number again at once: no second task, nothing overwritten.
  v_j := web_form_submit(v_tok, 'Someone Else', '971500249020', 'other@example.com', 'again', '{}');
  n := n + 1;
  IF v_j ->> 'status' <> 'ok' OR (v_j ->> 'task_created') <> 'false'
     OR (v_j ->> 'contact_id')::uuid <> c_new THEN
    failed := array_append(failed, ('a repeat submission returned: ' || v_j::text)::text);
  END IF;
  n := n + 1;
  IF (SELECT count(*) FROM tasks WHERE contact_id = c_new) <> 1
     OR (SELECT name FROM contacts WHERE id = c_new) <> 'Web Lead'
     OR (SELECT email FROM contacts WHERE id = c_new) <> 'lead@example.com' THEN
    failed := array_append(failed, 'a repeat submission opened a task or overwrote a field'::text);
  END IF;
  -- Ten minutes later it opens one again.
  UPDATE tasks SET created_at = now() - interval '11 minutes' WHERE contact_id = c_new;
  v_j := web_form_submit(v_tok, NULL, '971500249020', NULL, 'later', '{}');
  n := n + 1;
  IF (v_j ->> 'task_created') <> 'true' OR (SELECT count(*) FROM tasks WHERE contact_id = c_new) <> 2 THEN
    failed := array_append(failed, ('a submission after the window opened no task: ' || v_j::text)::text);
  END IF;

  -- ---- an existing contact -------------------------------------------------
  UPDATE contacts SET opted_out_at = now() - interval '1 day', email = NULL WHERE id = c_old;
  SELECT opted_out_at INTO v_ts FROM contacts WHERE id = c_old;
  -- The '+' form is refused: the route sends digits only.
  r := pg_temp.wlf_raw(format(
    'SELECT web_form_submit(%L, ''New Name'', ''+971500249010'', NULL, NULL, ''{}'')', v_tok));
  n := n + 1;
  IF r NOT LIKE 'ERROR 22023 bad_phone%' THEN
    failed := array_append(failed, ('a phone with + was accepted: ' || r)::text);
  END IF;
  v_j := web_form_submit(v_tok, 'New Name', '971500249010', 'old@example.com', NULL, '{}');
  n := n + 1;
  IF (v_j ->> 'contact_id')::uuid IS DISTINCT FROM c_old OR (v_j ->> 'contact_created') <> 'false' THEN
    failed := array_append(failed, ('an existing number made a new contact: ' || v_j::text)::text);
  END IF;
  n := n + 1;
  IF NOT EXISTS (
    SELECT 1 FROM contacts
     WHERE id = c_old AND name = 'Existing' AND email IS NULL
       AND lead_source = 'manual' AND user_id = u_agent
       AND opted_out_at = v_ts) THEN
    failed := array_append(failed, 'an existing contact''s name, email, source, owner or opt-out changed'::text);
  END IF;
  -- 256: what was submitted for an existing contact goes in the task.
  n := n + 1;
  IF NOT EXISTS (
    SELECT 1 FROM tasks
     WHERE contact_id = c_old AND source_ref LIKE 'web_form:%'
       AND meta ->> 'submitted_name' = 'New Name'
       AND meta ->> 'submitted_email' = 'old@example.com'
       AND note LIKE '%Submitted name: New Name%') THEN
    failed := array_append(failed, 'the submitted name and email are not in the existing contact''s task'::text);
  END IF;
  -- 256: even a name that is only the number (inbound's fallback) is
  -- left alone on an existing contact; the lead source still fills.
  INSERT INTO contacts (account_id, user_id, phone, name)
    VALUES (a_acct, u_agent, '971500249030', '971500249030') RETURNING id INTO c_out;
  v_j := web_form_submit(v_tok, 'Real Name', '971500249030', NULL, NULL, '{}');
  n := n + 1;
  IF (SELECT name FROM contacts WHERE id = c_out) <> '971500249030'
     OR (SELECT lead_source FROM contacts WHERE id = c_out) <> 'web_form' THEN
    failed := array_append(failed, 'an existing contact''s number-only name was renamed, or no lead source'::text);
  END IF;

  -- ---- rotating --------------------------------------------------------------
  r := pg_temp.wlf_try(u_admin, 'SELECT web_form_set(true, ARRAY[''https://www.example.com''], true)');
  v_tok2 := CASE WHEN r LIKE 'ERROR%' THEN NULL ELSE r::jsonb ->> 'token' END;
  n := n + 1;
  IF v_tok2 IS NULL OR v_tok2 = v_tok OR v_tok2 !~ '^[0-9a-f]{64}$' THEN
    failed := array_append(failed, ('rotating did not issue a new token: ' || r)::text);
  END IF;
  n := n + 1;
  IF (web_form_submit(v_tok, 'X', '971500249040', NULL, NULL, '{}')) ->> 'status' <> 'not_found'
     OR web_form_public_config(v_tok) IS NOT NULL THEN
    failed := array_append(failed, 'the old token still works after rotating'::text);
  END IF;

  RAISE EXCEPTION USING ERRCODE = 'ZT249', MESSAGE = 'verify-web-lead-form rollback';
  EXCEPTION WHEN SQLSTATE 'ZT249' THEN
    NULL;
  END;

  IF array_length(failed, 1) > 0 THEN
    RAISE EXCEPTION 'web lead form verification: % of % checks failed: %',
      array_length(failed, 1), n, array_to_string(failed, ' | ');
  END IF;
  RAISE NOTICE 'web lead form verification passed (% checks)', n;
END
$verify$;
